// src/pages/Pedidos/Pedidos.tsx
import React, { useState } from "react";
import {
  IonPage,
  IonHeader,
  IonToolbar,
  IonTitle,
  IonContent,
  IonButton,
  IonInput,
  IonMenuButton,
  IonGrid,
  IonRow,
  IonCol,
  IonIcon,
  IonAlert,
  useIonViewWillEnter,
} from "@ionic/react";
import {
  cargarPedidos,
  filtrarPedidos,
  Pedido,
  eliminarPedido,
} from "../../utils/pedidosUtils";
import { useHistory } from "react-router-dom";
import { pencil, trash, documentText } from "ionicons/icons";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import "./Pedidos.css";

const Pedidos: React.FC = () => {
  const [pedidos, setPedidos] = useState<Pedido[]>([]);
  const [busqueda, setBusqueda] = useState("");
  const [showAlert, setShowAlert] = useState(false);
  const [alertMsg, setAlertMsg] = useState("");
  const [showDeleteSuccess, setShowDeleteSuccess] = useState(false);
  const history = useHistory();

  // Cargar pedidos al entrar a la vista
  useIonViewWillEnter(() => {
    cargarPedidos().then(setPedidos);
  });

  // Ordena los pedidos por fecha descendente (los más recientes primero)
  const mostrarTodos = busqueda === " ";
  const pedidosFiltrados = filtrarPedidos(
    pedidos,
    busqueda === " " ? "" : busqueda
  ).sort(
    (a, b) =>
      (b.fechaPedido ? new Date(b.fechaPedido).getTime() : 0) -
      (a.fechaPedido ? new Date(a.fechaPedido).getTime() : 0)
  );
  const pedidosAMostrar = mostrarTodos
    ? pedidosFiltrados
    : busqueda.trim() === ""
    ? pedidosFiltrados.slice(0, 5)
    : pedidosFiltrados;

  // Eliminar pedido y recargar lista
  const handleEliminarPedido = async (numeroPedido: string) => {
    if (window.confirm("¿Seguro que desea eliminar este pedido?")) {
      try {
        await eliminarPedido(numeroPedido);
        setShowDeleteSuccess(true);
        // Recarga la lista después de eliminar
        cargarPedidos().then(setPedidos);
      } catch (error: any) {
        setAlertMsg("Error al eliminar el pedido.");
        setShowAlert(true);
      }
    }
  };

  const exportarPDF = () => {
    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();
    const title = "Lista de Pedidos";
    const textWidth = doc.getTextWidth(title);
    const x = (pageWidth - textWidth) / 2;

    // Logo en base64 (puedes usar tu propio logo)
    const logoBase64 =
      "data:image/png;base64,"; // recorta por espacio

    // Agrega el logo (x, y, width, height)
    doc.addImage(logoBase64, "PNG", 10, 8, 15, 15);

    doc.text(title, x, 18);

    autoTable(doc, {
      head: [["ID", "Observación", "Estado", "Cliente", "Fecha"]],
      body: pedidosAMostrar.map((pedido) => [
        pedido.numeroPedido,
        pedido.EstadoPedido?.tipoEstado || "Sin estado",
        pedido.Cliente?.Persona
          ? `${pedido.Cliente.Persona.nombre} ${
              pedido.Cliente.Persona.apellido ?? ""
            }`.trim()
          : "Sin cliente",
        pedido.fechaPedido
          ? new Date(pedido.fechaPedido).toLocaleString("es-AR")
          : "",
      ]),
      startY: 28,
      styles: { fontSize: 10 },
      headStyles: { fillColor: [254, 175, 0] },
    });

    doc.save("pedidos.pdf");
  };

  return (
    <IonPage className="pedidos-page">
      <IonHeader>
        <IonToolbar>
          <IonMenuButton slot="start" />
          <IonTitle>Pedidos</IonTitle>
        </IonToolbar>
      </IonHeader>
      <IonContent className="pedidos-content">
        <IonGrid>
          {/* Fila 1: Buscador */}
          <IonRow>
            <IonCol size="12">
              <div className="pedidos-buscador">
                <IonInput
                  placeholder="Buscar por cliente, fecha o N° de pedido"
                  value={busqueda === " " ? "" : busqueda}
                  onIonChange={(e) => setBusqueda(e.detail.value!)}
                  clearInput
                  onKeyDown={(e) => {
                    if (
                      e.key === "Enter" &&
                      (!busqueda || busqueda.trim() === "")
                    ) {
                      setBusqueda(" "); // Fuerza a mostrar todos los pedidos
                    }
                  }}
                />
              </div>
            </IonCol>
          </IonRow>
          {/* Fila 2: Tabla */}
          <IonRow>
            <IonCol size="12">
              <div className="pedidos-table-wrapper">
                <IonGrid className="pedidos-table">
                  <IonRow className="table-header">
                    <IonCol className="text-center">
                      <strong>N° Pedido</strong>
                    </IonCol>
                    <IonCol className="text-center">
                      <strong>Estado</strong>
                    </IonCol>
                    <IonCol className="text-center">
                      <strong>Cliente</strong>
                    </IonCol>
                    <IonCol className="text-center">
                      <strong>Fecha</strong>
                    </IonCol>
                    <IonCol className="text-center">
                      <strong>Acciones</strong>
                    </IonCol>
                  </IonRow>
                  {pedidosAMostrar.map((pedido) => (
                    <IonRow key={pedido.numeroPedido} className="table-row">
                      <IonCol className="text-center">
                        {pedido.numeroPedido}
                      </IonCol>
                      <IonCol className="text-center">
                        {pedido.EstadoPedido?.tipoEstado || "Sin estado"}
                      </IonCol>
                      <IonCol className="text-center">
                        {pedido.Cliente?.Persona
                          ? `${pedido.Cliente.Persona.nombre} ${
                              pedido.Cliente.Persona.apellido ?? ""
                            }`.trim()
                          : "Sin cliente"}
                      </IonCol>
                      <IonCol className="text-center">
                        {pedido.fechaPedido
                          ? new Date(pedido.fechaPedido).toLocaleString("es-AR")
                          : ""}
                      </IonCol>
                      <IonCol className="text-center">
                        <div className="action-buttons">
                          <IonButton
                            fill="clear"
                            onClick={() =>
                              history.push(
                                `/alta-pedido/${pedido.numeroPedido}`
                              )
                            }
                          >
                            <IonIcon icon={pencil} color="primary" />
                          </IonButton>
                          <IonButton
                            fill="clear"
                            onClick={() =>
                              handleEliminarPedido(pedido.numeroPedido)
                            }
                            className="delete-btn"
                          >
                            <IonIcon icon={trash} color="danger" />
                          </IonButton>
                          <IonButton
                            fill="clear"
                            onClick={() =>
                              history.push(
                                `/detalle-pedido/${pedido.numeroPedido}`
                              )
                            }
                            className="detail-btn"
                          >
                            <IonIcon icon={documentText} color="medium" />
                          </IonButton>
                        </div>
                      </IonCol>
                    </IonRow>
                  ))}
                </IonGrid>
              </div>
            </IonCol>
          </IonRow>
          {/* Fila 3: Botón */}
          <IonRow>
            <IonCol size="12">
              <IonButton routerLink="/alta-pedido" expand="block">
                Nuevo Pedido
              </IonButton>
            </IonCol>
          </IonRow>
          <IonRow>
            <IonCol size="12">
              <IonButton expand="block" onClick={exportarPDF}>
                Exportar lista de pedidos a PDF
              </IonButton>
            </IonCol>
          </IonRow>
        </IonGrid>
        <IonAlert
          isOpen={showAlert}
          onDidDismiss={() => setShowAlert(false)}
          message={alertMsg}
          buttons={["Aceptar"]}
        />
        <IonAlert
          isOpen={showDeleteSuccess}
          message="Se eliminó correctamente el pedido"
          buttons={[
            {
              text: "Aceptar",
              handler: () => setShowDeleteSuccess(false),
            },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default Pedidos;
